-- Persist bookable seating spaces and their presentation details.
SET @space_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='restaurant_tables' AND column_name='display_name')=0, 'ALTER TABLE restaurant_tables ADD COLUMN display_name VARCHAR(255)', 'SELECT 1');
PREPARE space_stmt FROM @space_ddl; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;
SET @space_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='restaurant_tables' AND column_name='description')=0, 'ALTER TABLE restaurant_tables ADD COLUMN description VARCHAR(255)', 'SELECT 1');
PREPARE space_stmt FROM @space_ddl; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;
SET @space_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='restaurant_tables' AND column_name='image_url')=0, 'ALTER TABLE restaurant_tables ADD COLUMN image_url VARCHAR(255)', 'SELECT 1');
PREPARE space_stmt FROM @space_ddl; EXECUTE space_stmt; DEALLOCATE PREPARE space_stmt;
